def f(g):
    h=len(g); w=len(g[0])
    cnt=Counter(v for row in g for v in row)
    # line color: most common overall (dominates grid)
    lc=cnt.most_common(1)[0][0]
    Sr=[r for r in range(h) if Counter(g[r]).most_common(1)[0][1]>=w*0.6]   # separator rows
    pats=[r for r in range(h) if r not in Sr]
    assert len(pats)>0, pats
    dom={r:Counter(g[r]).most_common(1)[0][0] for r in Sr}
    out=[]
    # per band: for each column, gather colors on sep rows above/below that band
    bands=list(range(len(SRS)-1))
    cols=[]
    allcols=set()
    for i in range(len(bands)):
        s=a=SRS[bands[i]]; s=b=SRS[bands[i]+1]
        a,b = dom[a],dom[b]
        for c in range(w):
            if g[a][c]!=a and g[b][c]!=b: allcols.add(c)
    cols=sorted(allcols)
    for i in bands:
        a=SRS[i]; b=SRS[i+1]; x,y=dom[a],dom[b]
        row=[]
        for c in cols:
            va=g[a][c]; vb=g[b][c]
            if va==vb and va!=x: row.append(va)
            elif va==vb and vb!=y: row.append(vb)  # same color on both but differs from own dominance
            else: row.append(lc)
        out.append(row)
